using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Playables;using UnityEngine.Animations;using Sandbox.CharacterSystem;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class ValidateLioraClothingFit {
 const string Data="Data/Liora/ClothingFit/";
 static void Write(BinaryWriter w,Vector3 p){w.Write(p.x);w.Write(p.y);w.Write(p.z);}
 static Vector3[] Skin(SkinnedMeshRenderer r,Transform root){var m=r.sharedMesh;var p=m.vertices;var d=new Vector3[p.Length];for(int s=0;s<m.blendShapeCount;s++){float weight=r.GetBlendShapeWeight(s)*.01f;if(weight==0)continue;m.GetBlendShapeFrameVertices(s,0,d,null,null);for(int j=0;j<p.Length;j++)p[j]+=d[j]*weight;}var matrices=r.bones.Select((b,j)=>root.worldToLocalMatrix*b.localToWorldMatrix*m.bindposes[j]).ToArray();var result=new Vector3[p.Length];using(var cs=m.GetBonesPerVertex())using(var ws=m.GetAllBoneWeights()){int at=0;for(int j=0;j<p.Length;j++)for(int k=0;k<cs[j];k++){var w=ws[at++];result[j]+=matrices[w.boneIndex].MultiplyPoint3x4(p[j])*w.weight;}}return result;}
 public static object Run(){
 if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");var root=PrefabUtility.LoadPrefabContents("Assets/_Sandbox/Characters/Liora/Candidate/Liora_Candidate.prefab");
 try{var config=JObject.Parse(File.ReadAllText(Data+"candidate.json"));var input=JObject.Parse(File.ReadAllText(Data+"binding_input.json"));int nb=input["bodyVertices"].Count();var face=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Face");var outfit=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Outfit");var animator=root.GetComponentInChildren<Animator>(true);var original=outfit.sharedMesh;var oldBones=outfit.bones;var fitted=AssetDatabase.LoadAssetAtPath<Mesh>((string)config["mesh"]);var bones=config["bonePaths"].Select(p=>root.transform.Find((string)p)).ToArray();if(bones.Any(b=>!b))throw new Exception("Missing native garment bone");
 var rest=root.GetComponentsInChildren<Transform>(true).ToDictionary(t=>t,t=>(t.localPosition,t.localRotation,t.localScale));var entries=new List<object>();float maxRadius=0,maxSeamGap=0;var weights=JObject.Parse(File.ReadAllText(Data+"fitted_weights.json"));
 outfit.sharedMesh=fitted;outfit.bones=bones;var neutral=Skin(outfit,root.transform);var groups=input["clothVertices"].Select((p,i)=>new{key=Math.Round((float)p[0]*100000)+":"+Math.Round((float)p[1]*100000)+":"+Math.Round((float)p[2]*100000),index=i}).GroupBy(p=>p.key).Where(g=>g.Count()>1).Select(g=>g.Select(p=>p.index).ToArray()).ToArray();foreach(var g in groups)foreach(int i in g)maxSeamGap=Mathf.Max(maxSeamGap,Vector3.Distance(neutral[i],neutral[g[0]]));if(maxSeamGap>2e-5f)throw new Exception("Neutral seam gap "+maxSeamGap);
 var cases=new[]{(asset:"Thinking",mode:"Activity",intervals:12),(asset:"Speaking happy",mode:"AA",intervals:12),(asset:"Speaking happy",mode:"FF",intervals:12),(asset:"Greeting",mode:"Activity",intervals:8)};
 using(var writer=new BinaryWriter(File.Create(Data+"activity_validation.bin"))){writer.Write(nb);writer.Write(outfit.sharedMesh.vertexCount);
 foreach(var item in cases){foreach(var p in rest){p.Key.localPosition=p.Value.Item1;p.Key.localRotation=p.Value.Item2;p.Key.localScale=p.Value.Item3;}var activity=AssetDatabase.LoadAssetAtPath<ActivityDefinition>("Assets/_Sandbox/Data/Activity/"+item.asset+".asset");if(!activity||!activity.Animation||!activity.Animation.Clip)throw new Exception("Missing actual activity "+item.asset);var graph=PlayableGraph.Create("Actual Liora activity clothing validation");try{graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var p=AnimationClipPlayable.Create(graph,activity.Animation.Clip);p.SetApplyFootIK(false);AnimationPlayableOutput.Create(graph,"pose",animator).SetSourcePlayable(p);graph.Play();
 for(int step=0;step<=item.intervals;step++){for(int s=0;s<face.sharedMesh.blendShapeCount;s++)face.SetBlendShapeWeight(s,0);p.SetTime(activity.Animation.Clip.length*step/item.intervals);graph.Evaluate(0);if(activity.Expression)foreach(var target in activity.Expression.Targets){int s=face.sharedMesh.GetBlendShapeIndex(target.Shape);if(s>=0)face.SetBlendShapeWeight(s,target.Weight);}if(item.mode=="AA")face.SetBlendShapeWeight(face.sharedMesh.GetBlendShapeIndex("viseme_aa"),60);if(item.mode=="FF")face.SetBlendShapeWeight(face.sharedMesh.GetBlendShapeIndex("viseme_FF"),70);root.GetComponent<CharacterFacialMeshSync>()?.Apply();var body=Skin(face,root.transform).Take(nb).ToArray();outfit.sharedMesh=original;outfit.bones=oldBones;var before=Skin(outfit,root.transform);outfit.sharedMesh=fitted;outfit.bones=bones;var after=Skin(outfit,root.transform);maxRadius=Mathf.Max(maxRadius,after.Max(v=>v.magnitude));if(!after.All(v=>float.IsFinite(v.x)&&float.IsFinite(v.y)&&float.IsFinite(v.z))||maxRadius>3)throw new Exception("Invalid garment motion");foreach(var g in groups)foreach(int i in g)maxSeamGap=Mathf.Max(maxSeamGap,Vector3.Distance(after[i],after[g[0]]));foreach(var v in body)Write(writer,v);foreach(var v in before)Write(writer,v);foreach(var v in after)Write(writer,v);entries.Add(new{activity=item.asset,mode=item.mode,phase=(float)step/item.intervals,clip=activity.Animation.Clip.name,expression=activity.Expression?activity.Expression.name:"Neutral"});}
 }finally{graph.Destroy();}}
 }
 if(maxSeamGap>3e-5f)throw new Exception("Animated seam gap "+maxSeamGap);var report=new{passed=true,poses=entries.Count,entries,maxGarmentRadiusM=maxRadius,maxCoincidentSeamGapM=maxSeamGap,sourceSkinPreserved=true,playModeTested=false};File.WriteAllText(Data+"activity_validation.json",JsonConvert.SerializeObject(report,Formatting.Indented));return new{passed=true,poses=entries.Count,maxSeamGap};
 }finally{PrefabUtility.UnloadPrefabContents(root);}
 }
}
